    }
    fmt.Println(i)
}


Labels for Nested Loops
outer:
for i := 0; i &lt; 3; i++ {
    for j := 0; j &lt; 3; j++ {
        if i == 1 && j == 1 {
            break outer  // Break both loops
        }
    }
}

