    st.Push("a")
    st.Push("b")
    top, ok := st.Pop()
    fmt.Println("stack pop:", top, ok)

    set := NewSet[int]()
    set.Add(1)
    set.Add(1)
    set.Add(2)
    fmt.Println("set has 1:", set.Contains(1))
    fmt.Println("set has 3:", set.Contains(3))
