// clamp.go
package main

func Clamp(v, lo, hi int) int {
    if lo &gt; hi {
        lo, hi = hi, lo
    }
    if v &lt; lo {
        return lo
    }
    if v &gt; hi {
        return hi
    }
    return v
}

func InRange(v, lo, hi int) bool {
    return Clamp(v, lo, hi) == v
}
