func TestClamp(t *testing.T) {
    tests := []struct {
        name       string
        v, lo, hi  int
        want       int
    }{
        {"inside", 5, 0, 10, 5},
        {"low", -1, 0, 10, 0},
        {"high", 99, 0, 10, 10},
        {"swapped bounds", 5, 10, 0, 5},
    }
    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            if got := Clamp(tt.v, tt.lo, tt.hi); got != tt.want {
                t.Fatalf("Clamp(%d,%d,%d)=%d want %d", tt.v, tt.lo, tt.hi, got, tt.want)
            }
        })
    }
}

