package main

import (
    "fmt"
    "sync"
)

func main() {
    // 1) Goroutines + WaitGroup (no Sleep)
    var wg sync.WaitGroup
    for i := 1; i &lt;= 3; i++ {
        wg.Add(1)
        go func(n int) {
            defer wg.Done()
            fmt.Printf("goroutine %d done\n", n)
        }(i)
    }
    wg.Wait()
    fmt.Println("all goroutines finished")

    // 2) Unbuffered channel: send happens in another goroutine
    ch := make(chan string)
    go func() {
        ch &lt;- "hello from channel"
    }()
    fmt.Println(&lt;-ch)

    // 3) Tiny worker pool: jobs → workers → results
    jobs := make(chan int, 5)
    results := make(chan int, 5)

    const workers = 2
    var pool sync.WaitGroup
    for w := 1; w &lt;= workers; w++ {
        pool.Add(1)
        go func(id int) {
            defer pool.Done()
            for job := range jobs {
                results &lt;- job * 2
            }
        }(w)
    }

    for j := 1; j &lt;= 5; j++ {
        jobs &lt;- j
    }
    close(jobs)

    go func() {
        pool.Wait()
        close(results)
    }()

    sum := 0
    for r := range results {
        sum += r
    }
    fmt.Println("worker pool sum:", sum)
}
Expected output: (goroutine lines may appear in any order)
goroutine 1 done
goroutine 2 done
goroutine 3 done
all goroutines finished
hello from channel
worker pool sum: 30
What to notice: WaitGroup replaces time.Sleep for joining. Closing jobs lets workers exit range; closing results after pool.Wait() ends the collector cleanly.
