Fan-Out / Fan-In Architecture
The Fan-Out pattern distributes work across multiple worker goroutines reading from a single input channel. The Fan-In pattern consolidates the results from multiple worker channels back into a single output stream.
flow:
  ] -&gt; JobsCh[
  JobsCh -&gt; Worker1[
  JobsCh -&gt; Worker2[
  JobsCh -&gt; Worker3[
  Worker1 -&gt; Out1[
  Worker2 -&gt; Out2[
  Worker3 -&gt; Out3[
  Out1 -&gt; Multiplexer[
  Out2 -&gt; Multiplexer
  Out3 -&gt; Multiplexer
  Multiplexer -&gt; FinalCh[
// Worker function processing jobs from input channel
func worker(id int, jobs &lt;-chan int) &lt;-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for j := range jobs {
            // Process item (e.g. compute square)
            out &lt;- j * j
        }
    }()
    return out
}

// Fan-in: merge multiple worker output channels into one aggregated channel
func fanIn(channels ...&lt;-chan int) &lt;-chan int {
    out := make(chan int)
    var wg sync.WaitGroup

    for _, ch := range channels {
        wg.Add(1)
        go func(c &lt;-chan int) {
            defer wg.Done()
            for v := range c {
                out &lt;- v
            }
        }(ch)
    }

    go func() {
        wg.Wait()
        close(out)
    }()
    return out
}

More examples
Or-done pattern: stop ranging when an external done closes. Producer also selects on done so nothing hangs.
package main

import "fmt"

func orDone(done &lt;-chan struct{}, in &lt;-chan int) &lt;-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for {
            select {
            case &lt;-done:
                return
            case v, ok := &lt;-in:
                if !ok {
                    return
                }
                select {
                case out &lt;- v:
                case &lt;-done:
                    return
                }
            }
        }
    }()
    return out
}

func main() {
    done := make(chan struct{})
    in := make(chan int)

    go func() {
        defer close(in)
        for i := 1; i &lt;= 100; i++ {
            select {
            case &lt;-done:
                return
            case in &lt;- i:
            }
        }
    }()

    out := orDone(done, in)
    count := 0
    for v := range out {
        fmt.Println("v:", v)
        count++
        if count == 3 {
            close(done)
        }
    }
    fmt.Println("stopped early at", count)
}
