package main

import (
    "fmt"
    "sync"
)

type Cache struct {
    mu   sync.RWMutex
    data map[string]int
}

func (c *Cache) Get(k string) (int, bool) {
    c.mu.RLock()
    defer c.mu.RUnlock()
    v, ok := c.data[k]
    return v, ok
}

func (c *Cache) Set(k string, v int) {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data[k] = v
}

func main() {
    c := &Cache{data: map[string]int{}}
    var wg sync.WaitGroup

    // Writers
    for i := 0; i &lt; 10; i++ {
        wg.Add(1)
        go func(n int) {
            defer wg.Done()
            c.Set(fmt.Sprintf("k%d", n%3), n)
        }(i)
    }
    wg.Wait()

    // Readers
    for i := 0; i &lt; 3; i++ {
        wg.Add(1)
        go func(n int) {
            defer wg.Done()
            k := fmt.Sprintf("k%d", n)
            v, ok := c.Get(k)
            fmt.Printf("get %s -&gt; %d ok=%v\n", k, v, ok)
        }(i)
    }
    wg.Wait()
}
