package main

import (
    "context"
    "fmt"
    "sync"
)

func pool(ctx context.Context, jobs &lt;-chan int, workers int) &lt;-chan int {
    out := make(chan int)
    var wg sync.WaitGroup
    for w := 0; w &lt; workers; w++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for {
                select {
                case &lt;-ctx.Done():
                    return
                case j, ok := &lt;-jobs:
                    if !ok {
                        return
                    }
                    select {
                    case out &lt;- j * 2:
                    case &lt;-ctx.Done():
                        return
                    }
                }
            }
        }()
    }
    go func() {
        wg.Wait()
        close(out)
    }()
    return out
}

func main() {
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    jobs := make(chan int)
    results := pool(ctx, jobs, 3)

    go func() {
        defer close(jobs)
        for i := 1; i &lt;= 20; i++ {
            select {
            case &lt;-ctx.Done():
                return
            case jobs &lt;- i:
            }
        }
    }()

    count := 0
    for r := range results {
        _ = r
        count++
        if count == 5 {
            cancel() // stop early; remaining workers observe ctx.Done()
        }
    }
    fmt.Println("stopped after:", count)
}
