sync.Cond broadcast twice (reload signal).
package main

import (
    "fmt"
    "sync"
)

func main() {
    var mu sync.Mutex
    cond := sync.NewCond(&mu)
    generation := 0

    const workers = 3
    var wg sync.WaitGroup
    seen := make(chan int, workers*2)

    for i := 0; i &lt; workers; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            local := 0
            for local &lt; 2 {
                mu.Lock()
                for local == generation {
                    cond.Wait()
                }
                local = generation
                mu.Unlock()
                seen &lt;- local
            }
        }()
    }

    for g := 1; g &lt;= 2; g++ {
        mu.Lock()
        generation = g
        mu.Unlock()
        cond.Broadcast()
    }

    wg.Wait()
    close(seen)
    count := 0
    for range seen {
        count++
    }
    fmt.Println("signals delivered:", count) // 3 workers * 2 gens
}
