package main

import (
    "bytes"
    "encoding/json"
    "fmt"
)

type Event struct {
    Type string `json:"type"`
    N    int    `json:"n"`
}

func main() {
    var buf bytes.Buffer
    enc := json.NewEncoder(&buf)
    for i := 1; i &lt;= 3; i++ {
        if err := enc.Encode(Event{Type: "tick", N: i}); err != nil {
            panic(err)
        }
    }

    dec := json.NewDecoder(&buf)
    sum := 0
    for dec.More() {
        var e Event
        if err := dec.Decode(&e); err != nil {
            panic(err)
        }
        sum += e.N
        fmt.Printf("event type=%s n=%d\n", e.Type, e.N)
    }
    fmt.Println("sum:", sum)
}
Expected output:
event type=tick n=1
event type=tick n=2
event type=tick n=3
sum: 6

