Worked example
Slice preallocation vs grow-from-zero (benchmark pair).
Save as slice_test.go. Then:
go mod init example
go test -bench=. -benchmem
package main

import "testing"

func grow(n int) []int {
    var s []int
    for i := 0; i &lt; n; i++ {
        s = append(s, i)
    }
    return s
}

func prealloc(n int) []int {
    s := make([]int, 0, n)
    for i := 0; i &lt; n; i++ {
        s = append(s, i)
    }
    return s
}

func BenchmarkGrow(b *testing.B) {
    for i := 0; i &lt; b.N; i++ {
        _ = grow(1024)
    }
}

func BenchmarkPrealloc(b *testing.B) {
    for i := 0; i &lt; b.N; i++ {
        _ = prealloc(1024)
    }
}
Expected output: (Prealloc far fewer allocs)
BenchmarkGrow-8           ...   ... ns/op     ... B/op   ~10 allocs/op
BenchmarkPrealloc-8       ...   ... ns/op    8192 B/op     1 allocs/op

