package main

import (
    "fmt"
    "sync"
)

func racey(n int) int {
    var c int
    var wg sync.WaitGroup
    for i := 0; i &lt; n; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            c++
        }()
    }
    wg.Wait()
    return c
}

func fixed(n int) int {
    var c int
    var mu sync.Mutex
    var wg sync.WaitGroup
    for i := 0; i &lt; n; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            mu.Lock()
            c++
            mu.Unlock()
        }()
    }
    wg.Wait()
    return c
}

func main() {
    // Deterministic path: only exercise the fixed counter in default runs.
    // To see the race: temporarily print racey(1000) under `go run -race .`
    got := fixed(1000)
    fmt.Println("fixed count:", got)
    fmt.Println("ok:", got == 1000)
}
go run .
