package cigate

import "sync"

// BrokenAdd races on total (do not use in production).
func BrokenAdd(n int) int {
    var total int
    var wg sync.WaitGroup
    wg.Add(n)
    for i := 0; i &lt; n; i++ {
        go func() {
            defer wg.Done()
            total++
        }()
    }
    wg.Wait()
    return total
}

// SafeAdd uses an atomic-style mutex critical section.
func SafeAdd(n int) int {
    var total int
    var mu sync.Mutex
    var wg sync.WaitGroup
    wg.Add(n)
    for i := 0; i &lt; n; i++ {
        go func() {
            defer wg.Done()
            mu.Lock()
            total++
            mu.Unlock()
        }()
    }
    wg.Wait()
    return total
}
