func main() {
    tokens := []string{"Hello", " ", "world", "!"}
    h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        fl, ok := w.(http.Flusher)
        if !ok {
            http.Error(w, "no flush", 500)
            return
        }
