package main

import (
    "fmt"
    "net/http"
    "net/http/httptest"
    "net/http/httputil"
    "net/url"
    "sync"
    "sync/atomic"
)

type pool struct {
    mu    sync.Mutex
    addrs []string
    down  map[string]bool
    rr    uint64
}

func (p *pool) next() (string, bool) {
    p.mu.Lock()
    defer p.mu.Unlock()
    n := len(p.addrs)
    for i := 0; i &lt; n; i++ {
        idx := int(atomic.AddUint64(&p.rr, 1)-1) % n
        a := p.addrs[idx]
        if !p.down[a] {
            return a, true
        }
    }
    return "", false
}

func (p *pool) markDown(a string) {
    p.mu.Lock()
    p.down[a] = true
    p.mu.Unlock()
}

func main() {
    var hits [3]atomic.Int64
    var backends []*httptest.Server
    var addrs []string
    for i := 0; i &lt; 3; i++ {
        i := i
        ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
            if i == 1 && hits[1].Load() == 0 {
                // first touch on backend 1 fails once
            }
            hits[i].Add(1)
            fmt.Fprintf(w, "backend-%d", i)
        }))
        backends = append(backends, ts)
        u, _ := url.Parse(ts.URL)
        addrs = append(addrs, u.Host)
    }
    defer func() {
        for _, b := range backends {
            b.Close()
        }
    }()

    p := &pool{addrs: addrs, down: map[string]bool{}}
    // Mark middle backend down to show skip.
    p.markDown(addrs[1])

    proxy := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        addr, ok := p.next()
        if !ok {
            http.Error(w, "unavailable", http.StatusServiceUnavailable)
            return
        }
        rp := &httputil.ReverseProxy{
            Director: func(req *http.Request) {
                req.URL.Scheme = "http"
                req.URL.Host = addr
                req.Host = addr
                req.Header.Del("X-Internal-User") // strip spoofable header
            },
            ErrorHandler: func(w http.ResponseWriter, r *http.Request, err error) {
                p.markDown(addr)
                http.Error(w, "bad gateway", http.StatusBadGateway)
            },
        }
        rp.ServeHTTP(w, r)
    })

    front := httptest.NewServer(proxy)
    defer front.Close()

    for i := 0; i &lt; 6; i++ {
        resp, err := http.Get(front.URL + "/")
        if err != nil {
            fmt.Println("err", err)
            continue
        }
        var body [32]byte
        n, _ := resp.Body.Read(body[:])
        resp.Body.Close()
        fmt.Printf("req %d -&gt; %s\n", i+1, string(body[:n]))
    }
    fmt.Printf("hits: b0=%d b1=%d b2=%d\n", hits[0].Load(), hits[1].Load(), hits[2].Load())
}
