Graceful Shutdown Pattern
package main

import (
    "context"
    "errors"
    "log/slog"
    "net/http"
    "os"
    "os/signal"
    "syscall"
    "time"
)

func main() {
    ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
    defer stop()

    mux := http.NewServeMux()
    mux.HandleFunc("GET /work", func(w http.ResponseWriter, r *http.Request) {
        // Honor cancellation so Shutdown can finish.
        select {
        case &lt;-r.Context().Done():
            return
        case &lt;-time.After(2 * time.Second):
            w.Write([]byte("done"))
        }
    })

    srv := &http.Server{Addr: ":8080", Handler: mux, ReadHeaderTimeout: 5 * time.Second}

    errCh := make(chan error, 1)
    go func() {
        slog.Info("listening", "addr", srv.Addr)
        errCh &lt;- srv.ListenAndServe()
    }()

    select {
    case &lt;-ctx.Done():
        slog.Info("signal received, shutting down")
    case err := &lt;-errCh:
        if err != nil && !errors.Is(err, http.ErrServerClosed) {
            slog.Error("server failed", "err", err)
            os.Exit(1)
        }
    }

    shutdownCtx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
    defer cancel()
    if err := srv.Shutdown(shutdownCtx); err != nil {
        slog.Error("graceful shutdown failed", "err", err)
        _ = srv.Close()
        os.Exit(1)
    }
    slog.Info("bye")
}

Two-phase stop

Soft deadline (e.g. 15s): stop accepting, drain in-flight.
Hard deadline: cancel contexts, close forcibly, exit non-zero if work abandoned.

Kubernetes: terminationGracePeriodSeconds must be greater than your soft deadline, or you get SIGKILL mid-drain.

Child Processes

Always use context
cmd := exec.CommandContext(ctx, "ffmpeg", args...)
cmd.Stdout = &buf
cmd.Stderr = &errBuf
if err := cmd.Run(); err != nil {
    return fmt.Errorf("ffmpeg: %w: %s", err, errBuf.String())
}
When ctx cancels, Go sends SIGKILL to the child by default (after CommandContext cancel). For graceful child stop, start with cmd.Start(), signal SIGTERM, wait, then kill.
func runGraceful(ctx context.Context, name string, args ...string) error {
    cmd := exec.Command(name, args...)
    if err := cmd.Start(); err != nil {
        return err
    }
    done := make(chan error, 1)
    go func() { done &lt;- cmd.Wait() }()

    select {
    case err := &lt;-done:
        return err
    case &lt;-ctx.Done():
        _ = cmd.Process.Signal(syscall.SIGTERM)
        select {
        case err := &lt;-done:
            return err
        case &lt;-time.After(5 * time.Second):
            _ = cmd.Process.Kill()
            return &lt;-done
        }
    }
}


Avoid shell
