7. tailf — follow file growth
func tailf(ctx context.Context, path string, w io.Writer) error {
    f, err := os.Open(path)
    if err != nil {
        return err
    }
    defer f.Close()
    // seek end
    _, _ = f.Seek(0, io.SeekEnd)
    buf := make([]byte, 4096)
    for {
        n, err := f.Read(buf)
        if n &gt; 0 {
            _, _ = w.Write(buf[:n])
        }
        if err == io.EOF {
            select {
            case &lt;-ctx.Done():
                return nil
            case &lt;-time.After(200 * time.Millisecond):
            }
            continue
        }
        if err != nil {
            return err
        }
    }
}
