6. rotate — minimal size rotate (teaching only)
// if file size &gt; max: rename to .1 (overwrite), create new file
// NOT a full logrotate replacement — no copytruncate races covered fully
func rotateIfLarge(path string, max int64) error {
    st, err := os.Stat(path)
    if err != nil {
        return err
    }
    if st.Size() &lt; max {
        return nil
    }
    bak := path + ".1"
    _ = os.Remove(bak)
    if err := os.Rename(path, bak); err != nil {
        return err
    }
    f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY, 0o644)
    if err != nil {
        return err
    }
    return f.Close()
}
