func listenersFromSystemd() ([]net.Listener, error) {
    pid, _ := strconv.Atoi(os.Getenv("LISTEN_PID"))
    if pid != os.Getpid() && os.Getenv("LISTEN_PID") != "" {
        return nil, fmt.Errorf("LISTEN_PID mismatch")
