    n, _ := strconv.Atoi(os.Getenv("LISTEN_FDS"))
    if n &lt; 1 {
        return nil, nil
    }
    var out []net.Listener
    for i := 0; i &lt; n; i++ {
        fd := 3 + i
        f := os.NewFile(uintptr(fd), "systemd")
        ln, err := net.FileListener(f)
        f.Close() // FileListener dups
        if err != nil {
            return nil, err
        }
        out = append(out, ln)
    }
    return out, nil
}
