func newRegistry() *registry { return &registry{ttl: map[string]time.Time{}} }

func (r *registry) upsert(addr string, ttl time.Duration) {
    r.mu.Lock()
    r.ttl[addr] = time.Now().Add(ttl)
    r.mu.Unlock()
}

func (r *registry) list() []string {
    r.mu.Lock()
    defer r.mu.Unlock()
    now := time.Now()
    var out []string
    for a, exp := range r.ttl {
        if now.Before(exp) {
            out = append(out, a)
        } else {
            delete(r.ttl, a)
        }
    }
    return out
}

