Circuit Breaker Implementation (Educational)
type state int

const (
    stateClosed state = iota
    stateOpen
    stateHalfOpen
)

type Breaker struct {
    mu           sync.Mutex
    st           state
    failures     int
    successes    int
    openUntil    time.Time
    failThreshold int
    successThreshold int
    cooldown     time.Duration
}

func (b *Breaker) Allow() bool {
    b.mu.Lock()
    defer b.mu.Unlock()
    now := time.Now()
    switch b.st {
    case stateOpen:
        if now.After(b.openUntil) {
            b.st = stateHalfOpen
            b.successes = 0
            return true // probe
        }
        return false
    default:
        return true
    }
}

func (b *Breaker) Report(err error) {
    b.mu.Lock()
    defer b.mu.Unlock()
    if err == nil {
        b.failures = 0
        if b.st == stateHalfOpen {
            b.successes++
            if b.successes &gt;= b.successThreshold {
                b.st = stateClosed
            }
        }
        return
    }
    b.failures++
    if b.st == stateHalfOpen || b.failures &gt;= b.failThreshold {
        b.st = stateOpen
        b.openUntil = time.Now().Add(b.cooldown)
        b.failures = 0
    }
}
Usage:
if !breaker.Allow() {
    return ErrFailFast
}
v, err := call(ctx)
breaker.Report(err)
Production libraries (sony/gobreaker, resilience middleware) add sliding windows and metrics — use them when possible; understand the state machine first.

Combining Retry and Breaker
Order matters:
if !breaker.Allow() -&gt; fail fast (no retry storm)
else attempt with retry **inside** half-open carefully (often single probe)
Do not let every request retry while open; the breaker already decided.

