In-process TTL map
type entry struct {
    val any
    exp time.Time
}

type Cache struct {
    mu sync.Mutex
    m  map[string]entry
}

func (c *Cache) Get(k string) (any, bool) {
    c.mu.Lock()
    defer c.mu.Unlock()
    e, ok := c.m[k]
    if !ok || time.Now().After(e.exp) {
        delete(c.m, k)
        return nil, false
    }
    return e.val, true
}

func (c *Cache) Set(k string, v any, ttl time.Duration) {
    c.mu.Lock()
    c.m[k] = entry{val: v, exp: time.Now().Add(ttl)}
    c.mu.Unlock()
}

