        for {
            j, err := q.Receive(ctx)
            if err != nil { return }
            if err := handle(ctx, j); err != nil {
                if j.Attempt+1 &gt;= max {
                    _ = q.DeadLetter(ctx, j, err.Error())
                } else {
                    j.Attempt++
                    _ = q.Retry(ctx, j, backoff(j.Attempt))
                }
                continue
            }
            _ = q.Ack(ctx, j.ID)
        }
    }()
}

