func main() {
    ctx := context.Background()
    shutdown, err := initTracer(ctx) // set global TracerProvider + propagator
    if err != nil {
        log.Fatal(err)
    }
    defer func() {
        // Flush remaining spans on exit; bound the wait.
        ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
        defer cancel()
        _ = shutdown(ctx)
    }()

    // run server...
