const shards = 16

type sharded struct {
    ms [shards]struct {
        mu sync.Mutex
        m  map[string]int
    }
}

func (s *sharded) inc(key string) {
    h := fnv32(key) % shards
    sh := &s.ms[h]
    sh.mu.Lock()
    sh.m[key]++
    sh.mu.Unlock()
}
Sharding reduces collision probability; pick shard count relative to GOMAXPROCS and key distribution.

