package main

import (
    "fmt"
    "sync"
    "sync/atomic"
    "time"
)

func hotMutex(n, workers int) time.Duration {
    var mu sync.Mutex
    var c int
    var wg sync.WaitGroup
    start := time.Now()
    for w := 0; w &lt; workers; w++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for i := 0; i &lt; n; i++ {
                mu.Lock()
                c++
                mu.Unlock()
            }
        }()
    }
    wg.Wait()
    _ = c
    return time.Since(start)
}

func atomicCount(n, workers int) time.Duration {
    var c atomic.Int64
    var wg sync.WaitGroup
    start := time.Now()
    for w := 0; w &lt; workers; w++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for i := 0; i &lt; n; i++ {
                c.Add(1)
            }
        }()
    }
    wg.Wait()
    return time.Since(start)
}

func main() {
    const n, w = 20_000, 4
    fmt.Println("mutex", hotMutex(n, w))
    fmt.Println("atomic", atomicCount(n, w))
