Deep Integration Example: Streaming JSON Pipeline with Backpressure
package pipeline

import (
    "bufio"
    "context"
    "encoding/json"
    "errors"
    "io"
    "sync"
    "time"
)

type Event struct {
    ID   string `json:"id"`
    Type string `json:"type"`
}

func DecodeEvents(ctx context.Context, r io.Reader) (&lt;-chan Event, &lt;-chan error) {
    out := make(chan Event, 128)
    errCh := make(chan error, 1)

    go func() {
        defer close(out)
        defer close(errCh)

        dec := json.NewDecoder(bufio.NewReader(r))
        for {
            var e Event
            if err := dec.Decode(&e); err != nil {
                if errors.Is(err, io.EOF) {
                    return
                }
                errCh &lt;- err
                return
            }

            select {
            case &lt;-ctx.Done():
                errCh &lt;- ctx.Err()
                return
            case out &lt;- e:
            }
        }
    }()

    return out, errCh
}

func ProcessEvents(ctx context.Context, in &lt;-chan Event, workers int, fn func(Event) error) error {
    ctx, cancel := context.WithCancel(ctx)
    defer cancel()

    errCh := make(chan error, workers)
    var wg sync.WaitGroup

    for i := 0; i &lt; workers; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for e := range in {
                opCtx, stop := context.WithTimeout(ctx, 250*time.Millisecond)
                err := fn(e)
                stop()
                if opCtx.Err() != nil {
                    errCh &lt;- opCtx.Err()
                    cancel()
                    return
                }
                if err != nil {
                    errCh &lt;- err
                    cancel()
                    return
                }
            }
        }()
    }

    wg.Wait()
    close(errCh)
    for err := range errCh {
        if err != nil {
            return err
        }
    }
    return nil
}

