Defer Semantics
func f() {
    defer fmt.Println("second")
    defer fmt.Println("first") // LIFO
    fmt.Println("body")
}
// body, first, second

Arguments evaluated immediately
func g() {
    x := 1
    defer fmt.Println(x) // prints 1 even if x changes later
