sync.Pool
var bufPool = sync.Pool{
    New: func() any {
        b := make([]byte, 0, 32*1024)
        return &b
    },
}

func handle() {
    bp := bufPool.Get().(*[]byte)
    buf := (*bp)[:0]
    defer func() {
        if cap(buf) &gt; 64*1024 { // don't retain huge buffers
            return
        }
        *bp = buf
        bufPool.Put(bp)
    }()
    // append into buf...
}
Rules:

No correctness dependency — pool may drop items on GC.
Reset objects before Put (clear sensitive data).
Cap retention — avoid pooling multi-MB buffers forever.
Prefer pooling *[]byte or structs with slices, not giant value copies.

