func countDigitsInWords(phrase string) map[string]int {
    words := strings.Fields(phrase)
    type pair struct {
        word  string
        count int
    }
    out := make(chan pair)
    go func() {
        defer close(out)
        for _, w := range words {
            out &lt;- pair{w, countDigits(w)}
        }
    }()
    stats := map[string]int{}
    for p := range out {
        stats[p.word] = p.count
    }
    return stats
