// Channel style
func execute(cancel &lt;-chan struct{}, fn func() int) (int, error) {
    ch := make(chan int, 1)
    go func() { ch &lt;- fn() }()
    select {
    case res := &lt;-ch:
        return res, nil
    case &lt;-cancel:
        return 0, errors.New("canceled")
    }
}

// Context style
func execute(ctx context.Context, fn func() int) (int, error) {
    ch := make(chan int, 1)
    go func() { ch &lt;- fn() }()
    select {
    case res := &lt;-ch:
        return res, nil
    case &lt;-ctx.Done():
        return 0, ctx.Err()
    }
}
