Variadic files (like cat)
func run(args []string, stdout io.Writer) error {
    if len(args) == 0 {
        _, err := io.Copy(stdout, os.Stdin)
        return err
    }
    for _, path := range args {
        f, err := os.Open(path)
        if err != nil {
            return err
        }
        _, err = io.Copy(stdout, f)
        f.Close()
        if err != nil {
            return err
        }
    }
    return nil
}


