func run(ctx context.Context, args []string) error {
    // HTTP
    req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
    // ...
    // Exec
    cmd := exec.CommandContext(ctx, "sleep", "60")
    // Files: poll ctx in loops
    return workLoop(ctx)
