F. kv — subcommands with FlagSet (stdlib)
package main

import (
    "encoding/json"
    "flag"
    "fmt"
    "os"
    "sync"
)

type DB struct {
    mu   sync.Mutex
    Data map[string]string `json:"data"`
    path string
}

func openDB(path string) (*DB, error) {
    db := &DB{Data: map[string]string{}, path: path}
    b, err := os.ReadFile(path)
    if err != nil {
        if os.IsNotExist(err) {
            return db, nil
        }
        return nil, err
    }
    if err := json.Unmarshal(b, db); err != nil {
        return nil, err
    }
    if db.Data == nil {
        db.Data = map[string]string{}
    }
    return db, nil
}

func (db *DB) save() error {
    db.mu.Lock()
    defer db.mu.Unlock()
    b, err := json.MarshalIndent(db, "", "  ")
    if err != nil {
        return err
    }
    return os.WriteFile(db.path, b, 0o600)
}

func main() {
    if len(os.Args) &lt; 2 {
        fmt.Fprintln(os.Stderr, "usage: kv &lt;get|set|list&gt; ...")
        os.Exit(2)
    }
    path := os.Getenv("KV_DB")
    if path == "" {
        path = "kv.json"
    }
    db, err := openDB(path)
    if err != nil {
        fail(err)
    }
    switch os.Args[1] {
    case "get":
        err = cmdGet(db, os.Args[2:])
    case "set":
        err = cmdSet(db, os.Args[2:])
    case "list":
        err = cmdList(db, os.Args[2:])
    default:
        fmt.Fprintln(os.Stderr, "unknown command")
        os.Exit(2)
    }
    if err != nil {
        fail(err)
    }
}

func cmdGet(db *DB, args []string) error {
    fs := flag.NewFlagSet("get", flag.ContinueOnError)
    if err := fs.Parse(args); err != nil {
        return err
    }
    if fs.NArg() != 1 {
        return fmt.Errorf("usage: kv get KEY")
    }
    db.mu.Lock()
    v, ok := db.Data[fs.Arg(0)]
    db.mu.Unlock()
    if !ok {
        return fmt.Errorf("not found")
    }
    fmt.Println(v)
    return nil
}

func cmdSet(db *DB, args []string) error {
    fs := flag.NewFlagSet("set", flag.ContinueOnError)
    if err := fs.Parse(args); err != nil {
        return err
    }
    if fs.NArg() != 2 {
        return fmt.Errorf("usage: kv set KEY VALUE")
    }
    db.mu.Lock()
    db.Data[fs.Arg(0)] = fs.Arg(1)
    db.mu.Unlock()
    return db.save()
}

