package main

import (
    "encoding/json"
    "fmt"
    "os"
    "time"

    "github.com/spf13/cobra"
)

type Task struct {
    Text string    `json:"text"`
    At   time.Time `json:"at"`
}

func load(path string) ([]Task, error) {
    b, err := os.ReadFile(path)
    if err != nil {
        if os.IsNotExist(err) {
            return nil, nil
        }
        return nil, err
    }
    var t []Task
    return t, json.Unmarshal(b, &t)
}

func save(path string, tasks []Task) error {
    b, err := json.MarshalIndent(tasks, "", "  ")
    if err != nil {
        return err
    }
    return os.WriteFile(path, b, 0o600)
}

func main() {
    path := "tasks.json"
    root := &cobra.Command{Use: "todo", Short: "Tiny todo list"}

    add := &cobra.Command{
        Use:  "add TEXT...",
        Args: cobra.MinimumNArgs(1),
        RunE: func(cmd *cobra.Command, args []string) error {
            tasks, err := load(path)
            if err != nil {
                return err
            }
            text := args[0]
            for _, a := range args[1:] {
                text += " " + a
            }
            tasks = append(tasks, Task{Text: text, At: time.Now().UTC()})
            return save(path, tasks)
        },
    }

    list := &cobra.Command{
        Use: "list",
        RunE: func(cmd *cobra.Command, args []string) error {
            tasks, err := load(path)
            if err != nil {
                return err
            }
            for i, t := range tasks {
                fmt.Printf("%d.\t%s\t(%s)\n", i+1, t.Text, t.At.Format(time.RFC3339))
            }
            return nil
        },
    }

    root.AddCommand(add, list)
    if err := root.Execute(); err != nil {
        os.Exit(1)
    }
}
