    body := strings.NewReader(`{"A":2,"B":40}`)
    req = httptest.NewRequest(http.MethodPost, "/sum", body)
    req.Header.Set("Content-Type", "application/json")
    rr = httptest.NewRecorder()
    mux.ServeHTTP(rr, req)
