    seed := flag.Int64("seed", 42, "rng seed")
    demo := flag.Bool("demo-series", false, "use fixed series instead of random")
    flag.Parse()

    if *minR &lt; 1 || *maxR &lt; *minR {
        fmt.Fprintln(os.Stderr, "invalid min/max")
