package main

import (
    "context"
    "errors"
    "fmt"
    "math/rand"
    "sync"
    "time"
)

type Job struct {
    ID       int
    Payload  string
    Attempts int
}

type Runner struct {
    workers int
    maxTry  int
    jobs    chan Job
}

func NewRunner(workers, maxTry, queueSize int) *Runner {
    return &Runner{
        workers: workers,
        maxTry:  maxTry,
        jobs:    make(chan Job, queueSize),
    }
}

func (r *Runner) Enqueue(j Job) {
    r.jobs &lt;- j
}

func process(ctx context.Context, j Job) error {
    select {
    case &lt;-ctx.Done():
        return ctx.Err()
    case &lt;-time.After(100 * time.Millisecond):
        // simulate intermittent failure
        if rand.Intn(3) == 0 {
            return errors.New("temporary failure")
        }
        fmt.Printf("job %d ok payload=%q\n", j.ID, j.Payload)
        return nil
    }
}

func (r *Runner) Start(ctx context.Context) {
    var wg sync.WaitGroup
    for w := 1; w &lt;= r.workers; w++ {
        wg.Add(1)
        go func(workerID int) {
            defer wg.Done()
            for {
                select {
                case &lt;-ctx.Done():
                    return
                case j, ok := &lt;-r.jobs:
                    if !ok {
                        return
                    }

                    err := process(ctx, j)
                    if err == nil {
                        continue
                    }

                    j.Attempts++
                    if j.Attempts &lt; r.maxTry {
                        backoff := time.Duration(j.Attempts*200) * time.Millisecond
                        time.AfterFunc(backoff, func() { r.Enqueue(j) })
                        fmt.Printf("worker=%d retry job=%d attempt=%d err=%v\n", workerID, j.ID, j.Attempts, err)
                    } else {
                        fmt.Printf("worker=%d dead-letter job=%d err=%v\n", workerID, j.ID, err)
                    }
                }
            }
        }(w)
    }

    wg.Wait()
}

func (r *Runner) Stop() {
    close(r.jobs)
}

func main() {
    rand.Seed(time.Now().UnixNano())
    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
    defer cancel()

    r := NewRunner(4, 4, 64)
    for i := 1; i &lt;= 20; i++ {
        r.Enqueue(Job{ID: i, Payload: fmt.Sprintf("task-%d", i)})
    }

    go func() {
        &lt;-ctx.Done()
        r.Stop()
    }()

    r.Start(ctx)
}

