package main

import (
    "bufio"
    "context"
    "flag"
    "fmt"
    "io"
    "os"
    "os/signal"
    "syscall"
    "time"
)

func lastNLines(path string, n int) ([]string, error) {
    if n &lt; 0 {
        n = 0
    }
    f, err := os.Open(path)
    if err != nil {
        return nil, err
    }
    defer f.Close()

    buf := make([]string, 0, n)
    s := bufio.NewScanner(f)
    sbuf := make([]byte, 0, 64*1024)
    s.Buffer(sbuf, 1024*1024)
    for s.Scan() {
        if n == 0 {
            continue
        }
        if len(buf) == n {
            copy(buf, buf[1:])
            buf[n-1] = s.Text()
        } else {
            buf = append(buf, s.Text())
        }
    }
    return buf, s.Err()
}

func follow(ctx context.Context, path string, offset int64, poll time.Duration) error {
    f, err := os.Open(path)
    if err != nil {
        return err
    }
    defer f.Close()

    if _, err := f.Seek(offset, io.SeekStart); err != nil {
        return err
    }

    for {
        select {
        case &lt;-ctx.Done():
            return nil
        default:
        }
        n, err := io.Copy(os.Stdout, f)
        if err != nil {
            return err
        }
        if n == 0 {
            // optional: detect truncation/rotation via Stat size &lt; offset
            select {
            case &lt;-ctx.Done():
                return nil
            case &lt;-time.After(poll):
            }
        }
    }
}

func main() {
    n := flag.Int("n", 10, "show last n lines")
    followMode := flag.Bool("f", false, "follow file")
    poll := flag.Duration("poll", 500*time.Millisecond, "follow poll interval")
    flag.Parse()

    if flag.NArg() != 1 {
        fmt.Fprintln(os.Stderr, "usage: gtail [-n N] [-f] &lt;file&gt;")
        os.Exit(2)
    }

    path := flag.Arg(0)
    lines, err := lastNLines(path, *n)
    if err != nil {
        fmt.Fprintln(os.Stderr, err)
        os.Exit(1)
    }
    for _, line := range lines {
        fmt.Println(line)
    }

    if !*followMode {
        return
    }

    st, err := os.Stat(path)
    if err != nil {
        fmt.Fprintln(os.Stderr, err)
        os.Exit(1)
    }

    ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
    defer stop()

    if err := follow(ctx, path, st.Size(), *poll); err != nil {
        fmt.Fprintln(os.Stderr, err)
        os.Exit(1)
    }
}

