package main

import (
    "bufio"
    "flag"
    "fmt"
    "io"
    "os"
    "unicode"
)

type counts struct {
    lines int
    words int
    bytes int
}

func countReader(r io.Reader) (counts, error) {
    var c counts
    s := bufio.NewScanner(r)
    // Note: Scanner strips newlines; we approximate bytes as len(line)+1 per line.
    // For exact byte counts matching GNU wc, use raw Read and dual-pass logic (stretch).
    buf := make([]byte, 0, 64*1024)
    s.Buffer(buf, 1024*1024)
    for s.Scan() {
        line := s.Text()
        c.lines++
        c.bytes += len(line) + 1 // +1 for '\n' (last line without newline is imperfect)
        inWord := false
        for _, ch := range line {
            if unicode.IsSpace(ch) {
                inWord = false
                continue
            }
            if !inWord {
                c.words++
                inWord = true
            }
        }
    }
    return c, s.Err()
}

func printCounts(c counts, name string) {
    if name == "" {
        fmt.Printf("%8d %8d %8d\n", c.lines, c.words, c.bytes)
        return
    }
    fmt.Printf("%8d %8d %8d %s\n", c.lines, c.words, c.bytes, name)
}

func main() {
    flag.Parse()
    if flag.NArg() == 0 {
        c, err := countReader(os.Stdin)
        if err != nil {
            fmt.Fprintln(os.Stderr, err)
            os.Exit(1)
        }
        printCounts(c, "")
        return
    }

    var total counts
    var hadErr bool
    for _, path := range flag.Args() {
        f, err := os.Open(path)
        if err != nil {
            fmt.Fprintf(os.Stderr, "%s: %v\n", path, err)
            hadErr = true
            continue
        }
        c, err := countReader(f)
        _ = f.Close()
        if err != nil {
            fmt.Fprintf(os.Stderr, "%s: %v\n", path, err)
            hadErr = true
            continue
        }
        total.lines += c.lines
        total.words += c.words
        total.bytes += c.bytes
        printCounts(c, path)
    }
    if flag.NArg() &gt; 1 {
        printCounts(total, "total")
    }
    if hadErr {
        os.Exit(1)
    }
}

