type tickMsg struct{}

type sample struct {
    cpuPct   float64
    memPct   float64
    gorCount int
    ts       time.Time
}

type model struct {
    last sample
    err  error
}

func tickCmd() tea.Cmd {
    return tea.Tick(1*time.Second, func(time.Time) tea.Msg { return tickMsg{} })
}

func (m model) Init() tea.Cmd { return tickCmd() }

func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
    switch msg := msg.(type) {
    case tea.KeyMsg:
        if msg.String() == "q" || msg.String() == "ctrl+c" {
            return m, tea.Quit
        }
    case tickMsg:
        cp, err := cpu.Percent(0, false)
        if err != nil || len(cp) == 0 {
            m.err = err
            return m, tickCmd()
        }
        vm, err := mem.VirtualMemory()
        if err != nil {
            m.err = err
            return m, tickCmd()
        }
        m.last = sample{
            cpuPct:   cp[0],
            memPct:   vm.UsedPercent,
            gorCount: runtime.NumGoroutine(),
            ts:       time.Now(),
        }
        m.err = nil
        return m, tickCmd()
    }
    return m, nil
}

func (m model) View() string {
    title := lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("86")).Render("GoTop - System Monitor")
    if m.err != nil {
        return fmt.Sprintf("%s\n\nerror: %v\n\npress q to quit\n", title, m.err)
    }
