package main

import (
    "log"
    "net/http"
    "sync"
    "time"

    "github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
    CheckOrigin: func(r *http.Request) bool { return true }, // lab only
}

type hub struct {
    mu      sync.Mutex
    clients map[*websocket.Conn]struct{}
}

func (h *hub) add(c *websocket.Conn) {
    h.mu.Lock()
    defer h.mu.Unlock()
    h.clients[c] = struct{}{}
}

func (h *hub) del(c *websocket.Conn) {
    h.mu.Lock()
    defer h.mu.Unlock()
    delete(h.clients, c)
    _ = c.Close()
}

func (h *hub) broadcast(msg []byte) {
    h.mu.Lock()
    defer h.mu.Unlock()
    for c := range h.clients {
        _ = c.SetWriteDeadline(time.Now().Add(5 * time.Second))
        if err := c.WriteMessage(websocket.TextMessage, msg); err != nil {
            delete(h.clients, c)
            _ = c.Close()
        }
    }
}

func main() {
    h := &hub{clients: map[*websocket.Conn]struct{}{}}

    http.HandleFunc("/ws", func(w http.ResponseWriter, r *http.Request) {
        c, err := upgrader.Upgrade(w, r, nil)
        if err != nil {
            return
        }
        h.add(c)
        defer h.del(c)

        for {
            _, msg, err := c.ReadMessage()
            if err != nil {
                return
            }
            h.broadcast(msg)
        }
    })

    http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Content-Type", "text/html; charset=utf-8")
        _, _ = w.Write([]byte(indexHTML))
    })

    log.Println("chat on http://localhost:8090/  ws://localhost:8090/ws")
    log.Fatal(http.ListenAndServe(":8090", nil))
}

const indexHTML = `&lt;!doctype html&gt;
&lt;title&gt;gochat&lt;/title&gt;
&lt;pre id="log"&gt;&lt;/pre&gt;
&lt;input id="m" placeholder="message"/&gt;&lt;button onclick="send()"&gt;send&lt;/button&gt;
&lt;script&gt;
const log = (t) =&gt; { logEl.textContent += t + "\n"; };
const logEl = document.getElementById("log");
const ws = new WebSocket("ws://" + location.host + "/ws");
ws.onmessage = (e) =&gt; log("&lt; " + e.data);
ws.onopen = () =&gt; log("connected");
function send() {
  const v = document.getElementById("m").value;
  ws.send(v);
  log("&gt; " + v);
}
&lt;/script&gt;`

